                // !!! Error: {} !!!\n\n" , e) ; let content_with_error_comment = error_comment + & initial_content ; fs :: write (lib_rs_path , content_with_error_comment) . context (format ! ("Failed to write unformatted new lib.rs with error comment to {}" , lib_rs_path . display ())) ? ; eprintln ! ("\n<blip style='color:red'>Formatting error for new lib.rs (written to {})</blip>" , lib_rs_path . display ()) ; } } println ! ("Rewrote {} to a minimalist version." , lib_rs_path . display ()) ; Ok (()) }